"""Read report/source text only; report-copy mutations never touch app code."""
import json,pathlib,copy,hashlib,ast,re
ROOT=pathlib.Path(__file__).resolve().parents[1]; OUT=ROOT/'.observe'; EV=OUT/'evidence'
read=lambda p:json.loads(p.read_text())
src=read(ROOT/'eval/inputs/agent-resource-cases.json'); report=read(OUT/'agent-resource-cases.json'); audit=read(OUT/'otel-audit.json')

def expected(raw):
 s=raw['source']; is_agent=('while True' in s and 'response.tool_calls' in s and 'messages.append' in s) or ('for {' in s and 'reply.Calls' in s and 'ToolResult(call.ID, value)' in s)
 return {'invoke_agent':None,'chat':'invoke_agent','execute_tool':'invoke_agent'} if is_agent else {'chat':None}

def check(r):
 errors=[]; counts={'operation':0,'field':0,'lifecycle':0,'current_components':0,'routing':0,'state':0}
 if set(r['cases'])!=set(src['cases']):errors.append('supplied case inventory mismatch')
 for name,case in r['cases'].items():
  raw=src['cases'][name]; source=raw['source']; ops=expected(raw); language='go' if 'func RunAgent' in source else 'python'
  destination='galileo' if 'GalileoSpanProcessor' in source else 'studio' if 'invoke_agent' in ops else 'ordinary-otel'
  if case['source_sha256']!=hashlib.sha256(source.encode()).hexdigest():errors.append(name+': stale source digest')
  if case['selected_destination']!=destination:errors.append(name+': destination differs from source-owned selection')
  if case['language']!=language:errors.append(name+': language differs')
  if {n['operation'] for n in case['operation_ledger']}!=set(ops):errors.append(name+': operation inventory differs from model/dispatch/feedback source')
  for collection in ['operation_ledger','field_acceptance_and_provenance','lifecycle_and_delivery']:
   for row in case[collection]:
    counts[{'operation_ledger':'operation','field_acceptance_and_provenance':'field','lifecycle_and_delivery':'lifecycle'}[collection]]+=1
    if row['operation'] not in ops:errors.append(name+': '+collection+' invents absent operation '+row['operation'])
    if 'parent' in row and row['parent']!=ops.get(row['operation']):errors.append(name+': '+collection+' absent/wrong parent '+str(row['parent']))
  for component in case['provider_ledger']['current']:
   counts['current_components']+=1
   registration=component.get('registration','')
   if not registration or re.sub(r'\s','',registration) not in re.sub(r'\s','',source):errors.append(name+': existing '+component['component']+' lacks source registration')
  no_exporter='OTLPSpanExporter(' not in source
  if no_exporter and any(x['component']=='OTLPSpanExporter' for x in case['provider_ledger']['current']):errors.append(name+': nonexistent existing HTTP exporter')
  route=case['routing'];counts['routing']+=1
  if route['language']!=language or route['destination']!=destination:errors.append(name+': routing language/destination mismatch')
  active_text=route['required_fix']+' '+json.dumps(route['acceptance_criteria'])
  # Every active inherited scenario participates in the language/destination check.
  for ref in route['acceptance_refs']:
   shared=r['shared_acceptance'].get(ref)
   if not shared:errors.append(name+': undefined acceptance reference '+ref);continue
   if shared['destination']!=destination:errors.append(name+': destination mismatch inherited '+ref+' ('+shared['destination']+' vs '+destination+')')
   active_text+=' '+json.dumps(shared)
  for state,value in case['studio_states'].items():
   counts['state']+=1
   for ref in value['acceptance_refs']:
    shared=r['shared_acceptance'].get(ref)
    if not shared or shared['destination']!=destination:errors.append(name+': state acceptance destination mismatch '+ref)
  if language=='go' and re.search(r'SpanExporter\.export|\bReadableSpan\b',active_text):errors.append(name+': Python API pasted into selected Go routing required_fix/acceptance')
  if language=='go' and not all(x in route['required_fix'] for x in ['NEW','ExportSpans(context.Context, []sdktrace.ReadOnlySpan) error','Shutdown(context.Context) error','Resource()']):errors.append(name+': missing new native Go exporter and language-bound public carrier contract')
  if name=='non_agent_control':
   for key in ['project','stream']:
    if case[key]['status']!='N/A':errors.append(name+': mandatory AO '+key+' on non-agent')
   if route['acceptance_refs']:errors.append(name+': AO acceptance on single inference')
  if destination=='galileo':
   profile=case['launch_profile']
   if profile.get('GALILEO_PROJECT')!='support' or profile.get('GALILEO_LOG_STREAM')!='production':errors.append(name+': changed native resource selectors')
   if name=='galileo_plus_native' and profile.get('INTERNAL_TRACE_ENDPOINT')!='http://127.0.0.1:55318/v1/traces':errors.append(name+': changed operator sink')
   # Correct provider/fix does not excuse destination-contaminated acceptance.
   direct=json.dumps(route['acceptance_criteria'])
   if re.search(r'projectid|logstreamid|splunk_ao\.project\.id|UUID.*Resource',direct):errors.append(name+': Studio UUID header/Resource activation in Galileo acceptance')
 # Complete names-only controls and distinct startup scenario must survive composition.
 names=r['shared_acceptance']['studio.native.names-only.same-pid']; txt=json.dumps(names).lower()
 for term in ['timeout','retry','backoff','business','telemetry','shutdown','cancel','same','zero creates']:
  if term not in txt:errors.append('names-only controls missing '+term)
 if not names['settings'] or any('gap' not in v for v in names['settings'].values()):errors.append('invented names-only runtime settings')
 start=r['native_startup_cases']['prevalidated_new_process_api_outage'];st=json.dumps(start).lower()
 for term in ['new application process','first exported batch','without successful resource relookup','503','connection refused','numeric-loopback','retained routing']:
  if term not in st:errors.append('distinct prevalidated startup missing '+term)
 return errors,counts

# Independently inspect canonical callable ASTs and source roles, never imports.
module_ast={f:ast.parse((ROOT/f).read_text()) for f in ['chat_core.py','recommendations.py','roles.py','app.py','agent.py','otel_setup.py']}
functions={f:{n.name:n for n in ast.walk(t) if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))} for f,t in module_ast.items()}
canonical_ledger=[{'operation':'invoke_agent','source':'chat_core.py','function':'run_turn','parent':None,'role_evidence':'TOOLS passed to inference, dispatch then result feedback and repeated inference','current_creator':'start_as_current_span, existing invoke_workflow label wrong','proposed_creator':'same existing span, same-span semantic repair'}, {'operation':'chat','source':'chat_core.py','function':'_chat_completion','parent':'invoke_agent','current_creator':'start_as_current_span CLIENT','proposed_creator':'preserved native same-span'}, {'operation':'execute_tool','source':'chat_core.py','function':'_dispatch_tool_call','parent':'invoke_agent','current_creator':'start_as_current_span INTERNAL','proposed_creator':'preserved native same-span'}, {'operation':'retrieval','source':'recommendations.py','function':'recommend_smash_burgers','parent':'execute_tool','current_creator':'none','proposed_creator':'new nested native span at actual normalized city corpus lookup'}, {'operation':'chat','source':'roles.py','function':'one_shot','parent':None,'current_creator':'none','proposed_creator':'one native CLIENT inference'}, {'operation':'invoke_workflow','source':'roles.py','function':'summarize_then_translate','parent':None,'current_creator':'none','proposed_creator':'one real fixed-composition native workflow'}, {'operation':'chat','source':'roles.py','function':'summarize_then_translate','parent':'invoke_workflow','current_creator':'none','proposed_creator':'two native CLIENT inference calls, summarize then translate'}]
canonical_errors=[]
for row in canonical_ledger:
 if row['function'] not in functions[row['source']]:canonical_errors.append('canonical absent function '+str(row))
core=(ROOT/'chat_core.py').read_text()
if not all(s in core for s in ['while message.tool_calls','_dispatch_tool_call(tool_call)','"role": "tool"','response = _chat_completion(client, model, messages)']):canonical_errors.append('canonical agent behavior lacks model/dispatch/feedback')
if not all(s in (ROOT/'recommendations.py').read_text() for s in ['normalized = city.strip().lower()','_CITY_RECOMMENDATIONS[normalized]','"recommendations": picks[:limit]']):canonical_errors.append('canonical retrieval dataflow absent')
# Bind every actual canonical operation/field/lifecycle row back to scoped source ledger.
canonical_rows=[]
for section in ['Operation and producer receipt: ','Field acceptance and provenance: ','Lifecycle and delivery: ']:
 for i,e in enumerate(audit['evidence']):
  if not e['check'].startswith(section):continue
  op=e['check'][len(section):].split()[0]
  owners=[x for x in canonical_ledger if x['operation']==op and x['source'] in e['source']]
  if not owners:canonical_errors.append('unowned canonical evidence '+e['check'])
  canonical_rows.append({'row':'evidence['+str(i)+']','kind':section.strip(': '),'operation':op,'source':e['source'],'matching_functions':[x['function'] for x in owners]})
for f in audit['findings']:
 for i,item in enumerate(f['expected_telemetry']):
  if item['type']=='span':
   if f['id']=='OTEL-001':ops=['invoke_agent']
   elif f['id']=='OTEL-002':ops=['chat']
   elif f['id']=='OTEL-003':ops=['execute_tool']
   elif f['id']=='OTEL-004':ops=['retrieval']
   elif f['id']=='OTEL-010':ops=['invoke_workflow'] if 'workflow' in item['name'] else ['chat']
   else:ops=[] # generic exception events on existing spans, not new GenAI operation
   canonical_rows.append({'row':f['id']+'.expected_telemetry['+str(i)+']','kind':'proposed span','operations':ops,'scope':f['evidence']})
# Provider ownership current vs proposed recorded alongside operation ledger.
canonical_topology={'web':{'current_provider':'otel_setup.py:143,161 TracerProvider global registration','current_exporter':'otel_setup.py:144 BatchSpanProcessor(OTLPSpanExporter())','proposed':'same native provider/exporter; language-bound SDK-free route delegation','destination':'ordinary configured OTLP retained; Studio AO candidate unverified'},'cli':{'current_provider':None,'current_exporter':None,'proposed':'new setup through shared configure_opentelemetry before calls, not preserved nonexistent CLI exporter','destination':'operator/local ordinary OTLP then selected native resource route'},'verification':{'current':'isolated in-memory providers in probe.py/historical_check.py, no live runtime coverage'}}
for f in audit['findings']:
 if f.get('finding_group')=='splunk-agent-observability' and 'runtime-routing' in f['area']:
  if 'SpanExporter.export' not in f['required_fix'] or 'ReadableSpan' not in f['required_fix']:canonical_errors.append(f['id']+': missing Python routing API')
  canonical_rows.append({'row':f['id'],'kind':'native Python routing/profile','source':f['evidence'],'current_vs_proposed':canonical_topology['cli' if '.cli.' in f['area'] else 'web']})
positive,counts=check(report)
controls=[]
def negative(name,mutate):
 r=copy.deepcopy(report);mutate(r);errors,_=check(r)
 controls.append({'name':name,'report_only':True,'outcome':'rejected' if errors else 'ERROR accepted','errors':errors,'application_source_changed':False})
negative('absent agent/model/tool-children lifecycle in single-inference facade',lambda r:r['cases']['non_agent_control']['lifecycle_and_delivery'].append({'operation':'invoke_agent','parent':None,'outcome':'agent with model/tool children','acceptance':'require agent -> chat and execute_tool'}))
negative('fresh Go nonexistent existing HTTP exporter',lambda r:r['cases']['fresh_native_fallback']['provider_ledger']['current'].append({'component':'OTLPSpanExporter','registration':'provider.add_span_processor(BatchSpanProcessor(OTLPSpanExporter()))','source':'fresh Go source'}))
negative('Python SpanExporter.export/ReadableSpan pasted into Go routing required_fix',lambda r:r['cases']['fresh_native_fallback']['routing'].__setitem__('required_fix',r['cases']['fresh_native_fallback']['routing']['required_fix']+' Use Python SpanExporter.export and ReadableSpan for activation.'))
negative('Studio names-only inherited acceptance injected into Galileo while provider/fix unchanged',lambda r:r['cases']['galileo']['routing']['acceptance_refs'].append('studio.native.names-only.same-pid'))
negative('Studio UUID header/Resource acceptance pasted directly into Galileo plus operator sink',lambda r:r['cases']['galileo_plus_native']['routing']['acceptance_criteria'].append('Names-only recovery activates projectid/logstreamid UUID headers and splunk_ao.project.id trace Resource.'))
# Check application inputs unchanged since the scan began.
before=read(EV/'source-hashes-before.json'); after={str(f.relative_to(ROOT)):hashlib.sha256(f.read_bytes()).hexdigest() for f in ROOT.rglob('*') if f.is_file() and '.observe' not in f.parts};unchanged=before==after
out={'kind':'source-ledger-consistency-result','status':'Pass' if not positive and not canonical_errors and unchanged and all(c['outcome']=='rejected' for c in controls) else 'Fail','input_sha256':hashlib.sha256((ROOT/'eval/inputs/agent-resource-cases.json').read_bytes()).hexdigest(),'baseline':{'errors':positive,'rows_checked':counts,'canonical_errors':canonical_errors,'canonical_rows_checked':len(canonical_rows)},'canonical_operation_ledger':canonical_ledger,'canonical_provider_exporter_destination_ledger':canonical_topology,'canonical_row_reconciliation':canonical_rows,'negative_controls':controls,'application_source_config_dependencies_tests_unchanged':unchanged,'execution_scope':'Static source/report consistency only. No model, SDK probe, application/test execution, cloud, provision, browser or UI.'}
(EV/'source-ledger-consistency.json').write_text(json.dumps(out,indent=2)+'\n')
report['consistency_check']={'outcome':out['status'],'artifact':'.observe/evidence/source-ledger-consistency.json','negative_controls':[{k:c[k] for k in ['name','outcome']} for c in controls],'scope':'all operation/parent/field/lifecycle/current-proposed topology/routing/profile/inherited-destination rows; source unchanged'}
(OUT/'agent-resource-cases.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({'status':out['status'],'baseline':out['baseline'],'negative_controls':out['negative_controls'],'source_unchanged':unchanged},indent=2))
if out['status']!='Pass':raise SystemExit(1)

