{
  "kind": "independent-source-cases",
  "limits": "These are separate source snapshots, not executed app runtimes or live resource/SDK proof. No credentials or resource receipts are supplied. Existing configured names are selectors, not verified resources.",
  "cases": {
    "fresh_ao": {
      "runtime": "Python >=3.11; no telemetry setup or active vendor integration",
      "source": "def run_agent(client, messages, tools):
    while True:
        response = client.complete(messages=messages, tools=list(tools))
        messages.append(response.message)
        if not response.tool_calls:
            return response.text
        for call in response.tool_calls:
            result = tools[call.name](**call.arguments)
            messages.append({"role": "tool", "tool_call_id": call.id, "content": result})
"
    },
    "native_otel": {
      "runtime": "Python >=3.11",
      "source": "from opentelemetry import trace
from opentelemetry.sdk.trace import TracerProvider
from opentelemetry.sdk.trace.export import BatchSpanProcessor
from opentelemetry.exporter.otlp.proto.http.trace_exporter import OTLPSpanExporter
provider=TracerProvider()
provider.add_span_processor(BatchSpanProcessor(OTLPSpanExporter()))
trace.set_tracer_provider(provider)
def run_agent(client, messages, tools):
    while True:
        response = client.complete(messages=messages, tools=list(tools))
        messages.append(response.message)
        if not response.tool_calls:
            return response.text
        for call in response.tool_calls:
            result = tools[call.name](**call.arguments)
            messages.append({"role": "tool", "tool_call_id": call.id, "content": result})
"
    },
    "galileo": {
      "runtime": "Existing supported galileo[otel] SDK; native destination is configured by GALILEO_* settings",
      "source": "import os
from galileo.otel import GalileoSpanProcessor, add_galileo_span_processor
from opentelemetry import trace
from opentelemetry.sdk.trace import TracerProvider
provider=TracerProvider()
add_galileo_span_processor(provider, GalileoSpanProcessor(project=os.getenv("GALILEO_PROJECT")))
trace.set_tracer_provider(provider)
def run_agent(client, messages, tools):
    while True:
        response = client.complete(messages=messages, tools=list(tools))
        messages.append(response.message)
        if not response.tool_calls:
            return response.text
        for call in response.tool_calls:
            result = tools[call.name](**call.arguments)
            messages.append({"role": "tool", "tool_call_id": call.id, "content": result})
",
      "launch_profile": {
        "GALILEO_PROJECT": "support",
        "GALILEO_LOG_STREAM": "production",
        "GALILEO_CONSOLE_URL": "https://app.galileo.ai"
      }
    },
    "galileo_plus_native": {
      "runtime": "Existing Galileo SDK and distinct operator-owned OTLP sink",
      "source": "import os
from galileo.otel import GalileoSpanProcessor, add_galileo_span_processor
from opentelemetry import trace
from opentelemetry.sdk.trace import TracerProvider
from opentelemetry.sdk.trace.export import BatchSpanProcessor
from opentelemetry.exporter.otlp.proto.http.trace_exporter import OTLPSpanExporter
provider=TracerProvider()
add_galileo_span_processor(provider, GalileoSpanProcessor(project=os.getenv("GALILEO_PROJECT")))
provider.add_span_processor(BatchSpanProcessor(OTLPSpanExporter(endpoint=os.environ["INTERNAL_TRACE_ENDPOINT"])))
trace.set_tracer_provider(provider)
def run_agent(client, messages, tools):
    while True:
        response = client.complete(messages=messages, tools=list(tools))
        messages.append(response.message)
        if not response.tool_calls:
            return response.text
        for call in response.tool_calls:
            result = tools[call.name](**call.arguments)
            messages.append({"role": "tool", "tool_call_id": call.id, "content": result})
",
      "launch_profile": {
        "GALILEO_PROJECT": "support",
        "GALILEO_LOG_STREAM": "production",
        "INTERNAL_TRACE_ENDPOINT": "http://127.0.0.1:55318/v1/traces"
      }
    },
    "existing_ao": {
      "runtime": "Existing supported splunk-ao SDK; no resource selectors in the launch profile",
      "source": "from splunk_ao import log
def run_agent(client, messages, tools):
    while True:
        response = client.complete(messages=messages, tools=list(tools))
        messages.append(response.message)
        if not response.tool_calls:
            return response.text
        for call in response.tool_calls:
            result = tools[call.name](**call.arguments)
            messages.append({"role": "tool", "tool_call_id": call.id, "content": result})

run_agent = log(run_agent)
"
    },
    "fresh_native_fallback": {
      "runtime": "Go; bounded supplied support evidence establishes native OpenTelemetry support but no compatible AO creator SDK in this environment",
      "source": "func RunAgent(ctx context.Context, model Model, tools map[string]Tool, history []Message) (string, error) {
 for {
  reply, err := model.Complete(ctx, history, tools)
  if err != nil { return "", err }; history = append(history, reply.Message)
  if len(reply.Calls) == 0 { return reply.Text, nil }
  for _, call := range reply.Calls { value, err := tools[call.Name](ctx, call.Arguments); if err != nil { return "", err }; history = append(history, ToolResult(call.ID, value)) }
 }
}
"
    },
    "non_agent_control": {
      "runtime": "Python; no vendor integration or resource setup",
      "source": "def summarize(client, text):
    return client.complete(messages=[{"role":"user", "content":text}]).text
"
    }
  },
  "studio_states": {
