"""Executable report-only consistency audit; no service/SDK imports or network calls."""
import ast,copy,hashlib,json,pathlib,re
ROOT=pathlib.Path(__file__).resolve().parents[2];OUT=ROOT/'.observe'
def load(p):return json.loads(p.read_text())
def save(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
def digest(x):return hashlib.sha256(json.dumps(x,sort_keys=True,separators=(',',':')).encode()).hexdigest()
I=load(ROOT/'eval/inputs/agent-resource-cases.json'); original=load(OUT/'agent-resource-cases.json')
# Compute the allowed operations and registrations directly from the independent source.
TRUTH={}
for cid,c in I['cases'].items():
 s=c['source'];go='func RunAgent(' in s
 if go:
  agent=all(x in s for x in ['model.Complete(ctx, history, tools)','tools[call.Name](ctx, call.Arguments)','ToolResult(call.ID, value)','for {'])
 else:
  t=ast.parse(s);agent=any(isinstance(x,ast.While) for x in ast.walk(t)) and 'tools[call.name]' in s and 'messages.append' in s
 ops={'agent':None,'model':'agent','tool':'agent'} if agent else {'model':None}
 components=[]
 for name,marker in [('TracerProvider','provider=TracerProvider()'),('GalileoSpanProcessor','add_galileo_span_processor(provider,'),('OTLPSpanExporter','BatchSpanProcessor(OTLPSpanExporter('),('splunk_ao.log','run_agent = log(run_agent)')]:
  if marker in s:components.append(name)
 dest='galileo' if 'GalileoSpanProcessor(' in s else 'studio' if agent else 'ordinary-otel'
 owner='go-provider' if go else 'sdk-logger' if 'run_agent = log(run_agent)' in s else 'python-provider'
 apis=['TracerProvider.ForceFlush(ctx)','TracerProvider.Shutdown(ctx)','context.CancelFunc'] if go else ['SplunkAOLogger.flush()','SplunkAOLogger.terminate()'] if owner=='sdk-logger' else ['TracerProvider.force_flush()','TracerProvider.shutdown()']
 TRUTH[cid]={'role':'agent' if agent else 'single-inference facade','language':'go' if go else 'python','operations':ops,'components':components,'destination':dest,'owner':owner,'apis':apis,'source':s}

def validate(report):
 errors=[];checked=[]
 def fail(cid,path,why):errors.append({'case':cid,'path':path,'reason':why})
 def record(cid,path,category,owner,ops=(),shared_source=None):
  t=TRUTH[cid];reference_path=None
  if '->' in path:reference_path,path=path.split('->',1)
  checked.append({'case':cid,'json_path':path,'dereferenced_via_reference_json_path':reference_path,'category':category,'role_applicability':t['role'],'case_language':t['language'],'destination_owner':t['destination'],'capability_owner':owner,'operation_ids':list(ops),'dereferenced_shared_source_path':shared_source,'result':'checked'})
 def semantics(cid,text,path,category='acceptance',owner=None):
  t=TRUTH[cid]
  if t['language']=='go' and re.search(r'\bforce_flush\b|logger\.terminate|SplunkAOLogger|SpanExporter\.export|\bReadableSpan\b|SpanKind\.|start_as_current_span|start_splunk_ao_span',text):fail(cid,path,'foreign Python SDK/native carrier or lifecycle API in selected Go contract')
  if category=='acceptance' and t['owner']!='sdk-logger' and re.search(r'logger\.terminate|SplunkAOLogger\.terminate',text):fail(cid,path,'lifecycle alternatives belong to an unselected SDK sink; active acceptance must use selected provider owner')
  # Check positive obligations sentence by sentence; explicit N/A/negative scope is retained.
  for sentence in re.split(r'(?<=[.!?])\s+',text):
   negative=bool(re.search(r'\bN/A\b|\bno (?:project|Studio|resource|agent|outer agent)|not selected|not applicable',sentence,re.I))
   if t['role']!='agent' and not negative and re.search(r'actual supported resource result|(?:require|resolve|activate|activation|lookup).*project.?stream|project/stream resource resolution|binding activation|UUID.*Resource activation',sentence,re.I):fail(cid,path,'mandatory AO resource lookup/binding activation under non-agent AO N/A scope')
   if t['destination']=='galileo' and not negative and re.search(r'Studio.*(?:names.only|UUID|Resource activation)|projectid/logstreamid|splunk_ao\.project\.id|matching.*UUID.*Resource',sentence,re.I):fail(cid,path,'Studio UUID-header/Resource activation obligation belongs to a different destination')
  if not t['components'] and category in ['routing','topology'] and re.search(r'preserve (?:the )?existing (?:HTTP |trace |native )?exporter|merge .*existing .*exporter',text,re.I):fail(cid,path,'routing claims an existing exporter in fresh source with no registration')
 def check_clause(cid,c,path,shared_source=None):
  t=TRUTH[cid]
  if isinstance(c,str):
   semantics(cid,c,path);record(cid,path,'active acceptance text',t['owner'],shared_source=shared_source);return
  if not isinstance(c,dict):fail(cid,path,'acceptance item must be text or structured clause');return
  if t['role'] not in c.get('applies_to_roles',[]):fail(cid,path,'role applicability mismatch')
  if t['language'] not in c.get('case_languages',[]):fail(cid,path,'language applicability mismatch')
  if t['destination'] not in c.get('destination_owners',[]):fail(cid,path,'destination owner mismatch')
  missing=set(c.get('operation_ids',[]))-set(t['operations'])
  if missing:fail(cid,path,'absent source operations/parents: '+','.join(sorted(missing)))
  if t['role']!='agent' and c.get('obligation') in ['resource','binding']:fail(cid,path,'mandatory resource/binding obligation under AO N/A')
  if c.get('obligation')=='lifecycle':
   if c.get('capability_owner')!=t['owner']:fail(cid,path,'lifecycle owner differs from selected sink/provider')
   if set(c.get('api_symbols',[]))!=set(t['apis']):fail(cid,path,'active lifecycle API set does not match selected language/provider')
  semantics(cid,c.get('text',''),path,owner=c.get('capability_owner'))
  for i,a in enumerate(c.get('api_symbols',[])):semantics(cid,a,path+'/api_symbols/'+str(i))
  record(cid,path,'active acceptance',c.get('capability_owner'),c.get('operation_ids',[]),shared_source)
 def refs(cid,values,path):
  for i,key in enumerate(values):
   if key not in report['shared_acceptance']:fail(cid,path+'/'+str(i),'unresolved shared acceptance reference');continue
   for j,c in enumerate(report['shared_acceptance'][key]):check_clause(cid,c,path+'/'+str(i)+'->/shared_acceptance/'+key+'/'+str(j),'/shared_acceptance/'+key+'/'+str(j))
 if set(report['cases'])!=set(TRUTH):errors.append({'path':'/cases','reason':'case inventory mismatch'})
 for cid,t in TRUTH.items():
  c=report['cases'][cid];p='/cases/'+cid
  if (c['role'],c['language'],c['routing']['destination'])!=(t['role'],t['language'],t['destination']):fail(cid,p,'case scope disagrees with freshly inspected source')
  l=report['source_ledgers'][cid]
  if l['source_sha256']!=hashlib.sha256(t['source'].encode()).hexdigest():fail(cid,'/source_ledgers/'+cid,'source digest mismatch')
  for container,ops in [('source_ledgers',l['operations']),('cases',c['operation_and_producer_receipt'])]:
   if set(x['id'] for x in ops)!=set(t['operations']):fail(cid,p+'/'+container,'source operation inventory mismatch')
   for i,o in enumerate(ops):
    path=('/source_ledgers/'+cid+'/operations/' if container=='source_ledgers' else p+'/operation_and_producer_receipt/')+str(i)
    if o['id'] not in t['operations'] or o['parent']!=t['operations'].get(o['id']):fail(cid,path,'proposed operation or parent is absent from source ledger')
    elif o['kind']!=('CLIENT' if o['id']=='model' else 'INTERNAL'):fail(cid,path,'kind does not match actual source operation boundary')
    for key in ['creator','pattern','creation_time']:
     if key in o:semantics(cid,o[key],path+'/'+key,'producer')
    record(cid,path,'operation/parent/creator',t['owner'],[o['id']])
  top=c['provider_exporter_destination_ownership'];comps=[x['component'] for x in top['current_components']]
