"""Validate report copies against independently inspected source snapshots.

Only report data is mutated. The application, input snapshots, inventory and
canonical report are never rewritten by the negative controls.
"""
import copy
import hashlib
import json
import pathlib
import re

ROOT=pathlib.Path(__file__).resolve().parents[2]
OUT=ROOT/'.observe'
def read(p): return json.loads(p.read_text())
source=read(ROOT/'eval/inputs/agent-resource-cases.json')
report=read(OUT/'agent-resource-cases.json')
inherited=read(ROOT/'eval/inputs/routing-acceptance-counterexamples.json')

def facts(name):
 s=source['cases'][name]['source']
 agent=('while True:' in s or 'for {' in s) and ('tool_calls' in s or 'reply.Calls' in s) and ('messages.append' in s or 'history = append' in s)
 go=s.startswith('func ')
 current=[]
 if 'provider=TracerProvider()' in s: current.append(name+'.provider')
 if 'OTLPSpanExporter(' in s: current.append(name+'.otlp')
 if 'GalileoSpanProcessor(project=' in s: current.append(name+'.galileo')
 if 'run_agent = log(run_agent)' in s: current.append(name+'.sdk-log')
 return dict(role='agent' if agent else 'single-inference facade',language='go' if go else 'python',destination='galileo' if 'from galileo.otel' in s else 'studio' if agent else 'ordinary-otel',ops={'agent':None,'model':'agent','tool':'agent'} if agent else {'model':None},current=current)

def check(data, collect=False):
 errors=[]; checked=[]
 def fail(path,why): errors.append(dict(path=path,reason=why))
 def receipt(path,f,kind,**extra):
  if collect: checked.append(dict(path=path,role_applicability=f['role'],case_language=f['language'],destination_owner=f['destination'],kind=kind,**extra))
 def text_check(text,path,f,where):
  # These are forbidden positive foreign contracts, not words in source quotes.
  if f['language']=='go' and re.search(r'SpanExporter\.export|\bReadableSpan\b|force_flush\(|logger\.terminate|SplunkAOLogger\.terminate|provider\.shutdown\(',text):
   fail(path,'Python SDK lifecycle/carrier syntax is foreign to selected Go operation/route')
  if f['destination']=='galileo' and re.search(r'activate.*(?:UUID|projectid)|projectid/logstreamid.*(?:Resource|activate)|UUID trace.header.*Resource',text,re.I):
   fail(path,'Studio UUID trace-header/Resource activation is not Galileo-native acceptance')
  if f['role']!='agent':
   if re.search(r'agent.with.model/tool.children|agent lifecycle|invoke_agent|parent.?=.?agent',text,re.I): fail(path,'Non-agent source has only inference; agent/tool parent/lifecycle is absent')
   if re.search(r'(?:resolve|activate|require|mandatory).{0,35}(?:project/stream|resource binding|binding activation)|project/stream resource resolution',text,re.I): fail(path,'AO resource resolution/binding activation is N/A for non-agent source')
  if not f['current'] and re.search(r'preserv(?:e|ed|ing) (?:the |an |supplied |current |existing )*(?:native |HTTP |installed )*(?:provider|exporter)|existing HTTP exporter|preserve supplied installed',text,re.I):
   fail(path,'Empty current inventory cannot support preserve-current provider/exporter/installed-runtime claim')
  if f['language']=='go' and re.search(r'(?:Python.*(?:classes|Projects|AgentStreams).*(?:establish|prove|supported)|installed Go client support.*(?:Python|Projects))',text,re.I):
   if not re.search(r'NO installed Go support|not.*(?:establish|prove)|cannot',text,re.I): fail(path,'Python SDK class names do not establish Go installed client support')
  receipt(path,f,where)
 for name,c in data['source_ledger'].items():
  p='/source_ledger/'+name; f=facts(name)
  if c['role']!=f['role']: fail(p+'/role','Role contradicts source behavior')
  if c['language']!=f['language'] or c['destination']!=f['destination']: fail(p,'Case language/destination contradicts source')
  inventory=c['provider_exporter_destination_ownership']
  current=inventory['current_components']; proposed=inventory['proposed_components']; ids={x['id']:x for x in current+proposed}
  if [x['id'] for x in current]!=f['current']: fail(p+'/provider_exporter_destination_ownership/current_components','Current components differ from source registrations')
  for phase,rows in [('current',current),('proposed',proposed)]:
   for j,r in enumerate(rows):
    rp=p+'/provider_exporter_destination_ownership/'+phase+'_components/'+str(j)
    if r['phase']!=phase: fail(rp,'Component phase mismatch')
    if phase=='current' and not r['source_registration']: fail(rp,'Current component has no registration')
    if phase=='proposed' and r['source_registration'] is not None: fail(rp,'Proposed component falsely claims current registration')
    receipt(rp,f,'component inventory',component_id=r['id'],phase=phase)
  for r in current:
   expected=None if r['symbol']=='TracerProvider' else 'sdk-effective-destination-unverified' if r['symbol']=='splunk_ao.log' else 'galileo' if r['symbol']=='GalileoSpanProcessor' else 'operator-otlp' if name=='galileo_plus_native' else 'configured-otlp-unverified'
   if r['destination']!=expected:fail(p+'/provider_exporter_destination_ownership','Current destination is not backed by explicit source/config or its precise unknown scope')
  if c['launch_profile']!=source['cases'][name].get('launch_profile',{}):fail(p+'/launch_profile','Configured native/operator settings were changed in report')
  operation_ids={r['id'] for r in c['operation_and_producer_receipt']}
  if operation_ids!=set(f['ops']): fail(p+'/operation_and_producer_receipt','Operation set differs from reachable source ledger')
  for i,r in enumerate(c['operation_and_producer_receipt']):
   rp=p+'/operation_and_producer_receipt/'+str(i)
   if r['id'] not in f['ops'] or r['parent']!=f['ops'].get(r['id']): fail(rp,'Operation or parent unsupported by source')
   for key in ['creator_component_id','provider_component_id']:
    if r[key] not in ids: fail(rp+'/'+key,'Unknown inventory component ID')
   if r['creator_component_id'] in ids and r['component_phase']!=ids[r['creator_component_id']]['phase']: fail(rp,'Creator phase disagrees with inventory')
   if r['provider_component_id'] in ids and r['provider_phase']!=ids[r['provider_component_id']]['phase']: fail(rp,'Provider phase disagrees with inventory')
   runtime=r['runtime_version_receipt']
   for key,wanted in [('creator_component_id',r['creator_component_id']),('creator_phase',r['component_phase']),('provider_component_id',r['provider_component_id']),('provider_phase',r['provider_phase'])]:
    if runtime[key]!=wanted:fail(rp+'/runtime_version_receipt/'+key,'Runtime receipt ownership does not close against same inventory component/phase')
   if r['component_phase']=='current' and r['creator_component_id'] not in f['current']: fail(rp,'Current creator lacks source registration')
   for key in ['pattern','source_version','creator','creation_time']:
    text_check(r[key],rp+'/'+key,f,'operation/runtime receipt')
   receipt(rp,f,'operation and parent',operation_id=r['id'],parent=r['parent'],creator_component_id=r['creator_component_id'],provider_component_id=r['provider_component_id'],phase=r['component_phase'])
  for i,r in enumerate(c['field_acceptance_and_provenance']):
   rp=p+'/field_acceptance_and_provenance/'+str(i)
   if r['operation_id'] not in f['ops']: fail(rp,'Field assigned to absent source operation')
   if r['component_id'] not in ids or r['phase']!=ids.get(r['component_id'],{}).get('phase'): fail(rp,'Field component/phase unsupported')
   receipt(rp,f,'field ownership',operation_id=r['operation_id'],component_id=r['component_id'],phase=r['phase'])
  for i,r in enumerate(c['lifecycle_rows']):
   rp=p+'/lifecycle_rows/'+str(i)
   if not set(r['operation_ids'])<=set(f['ops']): fail(rp,'Lifecycle introduces absent operation')
   if r['provider_component_id'] not in ids: fail(rp,'Lifecycle owner not in inventory')
   for j,t in enumerate(r['symbols']): text_check(t,rp+'/symbols/'+str(j),f,'lifecycle symbol')
   text_check(r['required'],rp+'/required',f,'lifecycle requirement')
  resource=c['resource_api_auth_compatibility']; rp=p+'/resource_api_auth_compatibility'
  if f['role']=='agent':
   if resource['component_id'] not in ids or resource['phase']!=ids.get(resource['component_id'],{}).get('phase'): fail(rp,'Resource receipt must bind inventory component and phase')
  elif resource['status']!='N/A' or c['project']['status']!='N/A' or c['stream']['status']!='N/A': fail(rp,'Non-agent resource statuses must remain N/A')
  for key in ['language_neutral_http_evidence','language_specific_client_support']:
   text_check(resource[key],rp+'/'+key,f,'resource-client receipt')
  if 'inspected_language_neutral_contract' in resource:
   wire=resource['inspected_language_neutral_contract']
   if wire['client_component_id']!=resource['component_id'] or wire['phase']!=resource['phase']:fail(rp+'/inspected_language_neutral_contract','Wire receipt component/phase mismatch')
   receipt(rp+'/inspected_language_neutral_contract',f,'language-neutral HTTP source receipt',component_id=wire['client_component_id'],phase=wire['phase'])
  if resource['language']!=f['language'] or resource['destination_owner']!=f['destination']: fail(rp,'Resource receipt scope mismatch')
  routing=c['routing']; rp=p+'/routing'
  if routing['provider_component_id'] not in ids: fail(rp,'Route provider not in inventory')
  if routing['language']!=f['language'] or routing['destination']!=f['destination']: fail(rp,'Route scope mismatch')
  text_check(routing['required_fix'],rp+'/required_fix',f,'routing fix')
  for i,t in enumerate(routing['api_signatures']): text_check(t,rp+'/api_signatures/'+str(i),f,'routing API')
  def active(item,path):
   # Validate actual active text and dereference shared clauses in case scope.
   if item.get('language') not in (f['language'],'case-language'): fail(path,'Acceptance language owner mismatch')
   if item.get('destination_owner')!=f['destination']: fail(path,'Acceptance destination owner mismatch')
   if item.get('role_applicability')!=f['role']: fail(path,'Acceptance role owner mismatch')
   if 'shared_ref' in item:
    shared=data['shared_acceptance'][item['shared_ref']]
    if shared['destination_owner']!=f['destination'] or shared['role_applicability']!=f['role']: fail(path,'Shared scenario role/destination mismatch')
    receipt(path,f,'active shared reference',dereferenced_path='/shared_acceptance/'+item['shared_ref'])
    for j,t in enumerate(shared['clauses']):
     sp='/shared_acceptance/'+item['shared_ref']+'/clauses/'+str(j)
     text_check(t,sp,f,'dereferenced active shared clause')
     receipt(path+' -> '+sp,f,'shared clause in case scope')
    return
   if item.get('resource_obligation') and f['role']!='agent': fail(path,'Resource/binding activation item under AO N/A role')
   if not set(item.get('operation_ids',[]))<=set(f['ops']): fail(path,'Acceptance operation set unsupported')
   if item.get('lifecycle_owner') not in ids: fail(path,'Acceptance lifecycle owner unsupported')
   text_check(item['text'],path+'/text',f,'actual active acceptance')
   receipt(path,f,'active acceptance ownership',operations=item.get('operation_ids',[]),component_id=item.get('lifecycle_owner'))
  for i,item in enumerate(routing['acceptance_criteria']): active(item,rp+'/acceptance_criteria/'+str(i))
  for state,state_data in c['studio_states'].items():
   for j,item in enumerate(state_data['clauses']): active(item,p+'/studio_states/'+state+'/clauses/'+str(j))
   for branch,branch_data in state_data.get('branches',{}).items():
    for j,item in enumerate(branch_data['clauses']): active(item,p+'/studio_states/'+state+'/branches/'+branch+'/clauses/'+str(j))
  for startup,items in c['native_startup_cases'].items():
   for j,item in enumerate(items): active(item,p+'/native_startup_cases/'+startup+'/'+str(j))
  for i,item in enumerate(c.get('per_function_sdk_gate',[])):
   if item['operation_id'] not in f['ops']: fail(p+'/per_function_sdk_gate/'+str(i),'SDK gate for absent operation')
   receipt(p+'/per_function_sdk_gate/'+str(i),f,'per-function SDK capability decision')
  for i,item in enumerate(c.get('metric_applicability_inventory',[])):
   mp=p+'/metric_applicability_inventory/'+str(i)
   if item['operation_id'] is not None and item['operation_id'] not in f['ops']:fail(mp,'Metric operation unsupported')
   if item['provider_component_id'] not in ids or item['provider_phase']!=ids.get(item['provider_component_id'],{}).get('phase'):fail(mp,'Metric owner/phase not inventory-bound')
   receipt(mp,f,'metric applicability',component_id=item['provider_component_id'],phase=item['provider_phase'])
  for i,item in enumerate(c.get('semconv_closure_matrix',[])):
   if item['operation_id'] not in f['ops']:fail(p+'/semconv_closure_matrix/'+str(i),'Closure matrix introduces absent operation')
   receipt(p+'/semconv_closure_matrix/'+str(i),f,'semantic operation closure')
 return errors,checked

base_errors,paths=check(report,True)
controls=[]
def mutate(name,case,fn,claim):
 altered=copy.deepcopy(report)
 fn(altered['source_ledger'][case])
 errors,_=check(altered)
 controls.append(dict(id=name,case=case,report_only=True,mutation=claim,rejected=bool(errors),errors=errors,inventory_and_routing_fix_unchanged=altered['source_ledger'][case]['provider_exporter_destination_ownership']==report['source_ledger'][case]['provider_exporter_destination_ownership'] and altered['source_ledger'][case]['routing']['required_fix']==report['source_ledger'][case]['routing']['required_fix']))

def append_accept(c,text,ops=None,resources=False):
 item=copy.deepcopy(c['routing']['acceptance_criteria'][0]);item['text']=text
 if ops is not None:item['operation_ids']=ops
 item['resource_obligation']=resources
 c['routing']['acceptance_criteria'].append(item)

mutate('absent-agent-lifecycle','non_agent_control',lambda c:append_accept(c,'An agent with model/tool children lifecycle is mandatory.',['agent','model','tool']),'Insert agent-with-model/tool-children lifecycle into single-inference control; retain AO N/A statuses.')
mutate('absent-existing-http-exporter','fresh_native_fallback',lambda c:c['routing'].update(required_fix=c['routing']['required_fix']+' Preserve the existing HTTP exporter.'),'Claim existing HTTP exporter despite empty current_components.')
